package com.kartyavya.report.service; import com.kartyavya.report.dto.ReportDtos.*; import com.kartyavya.report.entity.*; import org.springframework.stereotype.Component; @Component public class ReportMapper{public ReportResponse response(Report r){return new ReportResponse(r.getId(),r.getTrackingCode(),r.getCitizenId(),r.getCitizenName(),r.getCitizenEmail(),r.getCitizenMobile(),r.getTitle(),r.getDescription(),r.getAreaLocation(),r.getImagePath(),r.getLatitude(),r.getLongitude(),r.getAiCategory().name(),r.getAiSeverity().name(),r.getAiConfidence(),r.isAiOverridden(),r.getSuggestedDepartmentCode(),r.getDepartmentId(),r.getDepartmentName(),r.getOfficerId(),r.getOfficerName(),r.getOfficerEmail(),r.getOfficerMobile(),r.getStatus().display(),r.getStatus().name(),r.getPendingReason(),r.getResolutionRemark(),r.getResolutionImagePath(),r.getCreatedAt(),r.getResolvedAt(),r.getVersion(),r.getStatusHistory().stream().map(h->new HistoryResponse(h.getFromStatus()==null?null:h.getFromStatus().name(),h.getToStatus().name(),h.getRemarks(),h.getChangedBy(),h.getChangedByRole(),h.getChangedAt())).toList());}public NearbyReportResponse nearby(Report r){return new NearbyReportResponse(r.getId(),r.getTitle(),r.getAreaLocation(),r.getLatitude(),r.getLongitude(),r.getAiCategory().name(),r.getAiSeverity().name(),r.getStatus().display(),r.getCreatedAt());}public TrackingResponse tracking(Report r){return new TrackingResponse(r.getTrackingCode(),r.getTitle(),r.getAreaLocation(),r.getAiCategory().name(),r.getAiSeverity().name(),r.getDepartmentName(),r.getOfficerName(),r.getStatus().display(),r.getPendingReason(),r.getCreatedAt(),r.getResolvedAt(),r.getStatusHistory().stream().map(h->new HistoryResponse(h.getFromStatus()==null?null:h.getFromStatus().name(),h.getToStatus().name(),h.getRemarks(),h.getChangedBy(),h.getChangedByRole(),h.getChangedAt())).toList());}}
